im=Image.new('RGBA',(2048,2048),'#38584A');d=ImageDraw.Draw(im);s=2048/108
def points(ps):return [(round(x*s),round(y*s)) for x,y in ps]
d.polygon(points([(18,28),(30,25),(42,27),(54,34),(66,27),(78,25),(90,28),(90,79),(78,76),(66,78),(54,85),(42,78),(30,76),(18,79)]),fill='#FAF7F1')
