for name,color in [('forest','#38584A'),('rose','#8B5155'),('paper','#786444')]:
    template=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1600" viewBox="0 0 1200 1600"><rect width="1200" height="1600" fill="#FAF7F1"/><rect x="64" y="64" width="1072" height="1472" rx="8" fill="none" stroke="{color}" stroke-width="3"/><path d="M128 250H1072M128 1320H1072" stroke="#C8A46B" stroke-width="2"/><text x="128" y="180" fill="{color}" font-family="Georgia,serif" font-size="56">LifeTalea</text><!-- Editable source: add a real title, photo and story in the application or design tool. --></svg>'''
